const { prisma } = await app("lib/prisma.ts");
const { updateWorkspaceSettingsAction } = await app("lib/actions/workspace-settings.ts");
const { requireWorkspaceAdmin } = await app("lib/workspace.ts");

// Create a user
const user = await prisma.user.create({ data: { email: "admin@example.com", name: "Admin User", passwordHash: "hashedpassword" } });

// Create a workspace with uppercase letters in webhookUrl to simulate the issue
const workspace = await prisma.workspace.create({
  data: {
    name: "Test Workspace",
    slug: "test-workspace",
    webhookUrl: "https://hooks.zapier.com/hooks/catch/1234567/AbCdEfG/",
    webhookSecret: "somesecret",
    slackSigningSecret: null,
  },
});

// Add membership with ADMIN role
await prisma.membership.create({ data: { userId: user.id, workspaceId: workspace.id, role: "ADMIN" } });

// Set session as the user
set_session({ user: { id: user.id, email: user.email } });

// Prepare a FormData helper function
function createFormData(data: Record<string, string | null | undefined>) {
  const fd = new Map();
  for (const [k, v] of Object.entries(data)) {
    fd.set(k, v ?? null);
  }
  return {
    get(key) {
      return fd.get(key);
    },
  };
}

